// Controlled private-peer test: generated bytes only, no files or user data.
import net from 'node:net';
import {once} from 'node:events';
import {setTimeout as delay} from 'node:timers/promises';
const [mode,address,other,portText]=process.argv.slice(2),port=Number(portText??other);
const allowed=['10.211.55.2','10.211.55.7'];
if(!allowed.includes(address)||![58443,58444].includes(port))throw Error('TEST_TARGET_NOT_APPROVED');
if(mode==='receive'){
 if(!allowed.includes(other)||other===address)throw Error('TEST_PEER_NOT_APPROVED');
 let total=0,connections=0;
 const server=net.createServer(socket=>{
  if(socket.remoteAddress!==other){socket.destroy();return;}
  connections++;let bytes=0;socket.setTimeout(20000,()=>socket.destroy());socket.write('KESHEV_CONTROLLED_RECEIVER\n');
  socket.on('data',data=>{bytes+=data.length;total+=data.length;if(bytes>16_000_000||total>180_000_000)socket.destroy();});
  socket.on('error',()=>{});socket.on('close',()=>console.log(JSON.stringify({kind:'received',bytes,total,connections,at:new Date().toISOString()})));
 });
 server.listen(port,address,()=>console.log(JSON.stringify({kind:'receiver-ready',port,privatePeerOnly:true})));
 setTimeout(()=>{server.close();process.exit(0);},1_900_000).unref();
}else{
 const connect=async()=>{
  const socket=net.createConnection({host:address,port});socket.setTimeout(4000,()=>socket.destroy(Error('TEST_CONNECT_TIMEOUT')));
  await once(socket,'connect');const [greeting]=await once(socket,'data');
  if(!greeting.toString().startsWith('KESHEV_CONTROLLED_RECEIVER')){socket.destroy();throw Error('WRONG_TEST_RECEIVER');}
  return socket;
 };
 if(mode==='probe'){
  try{const socket=await connect();socket.end();console.log(JSON.stringify({kind:'probe',accepted:true,at:new Date().toISOString()}));}
  catch{console.log(JSON.stringify({kind:'probe',accepted:false,at:new Date().toISOString()}));process.exitCode=2;}
 }else if(mode==='send'){
  const chunk=Buffer.alloc(250000,0x4b);let total=0;
  for(let connection=1;connection<=6;connection++){
   let socket;
   try{socket=await connect();socket.on('error',()=>{});await delay(2500);
    for(let n=0;n<56;n++){if(socket.destroyed)throw Error('TEST_TRANSFER_INTERRUPTED');if(!socket.write(chunk))await once(socket,'drain');total+=chunk.length;await delay(140);}
    socket.end();await once(socket,'close');console.log(JSON.stringify({kind:'sent',connection,total,at:new Date().toISOString()}));await delay(500);
   }catch{socket?.destroy();console.log(JSON.stringify({kind:'transfer-stopped',connection,total,at:new Date().toISOString()}));break;}
  }
 }else throw Error('TEST_MODE_INVALID');
}
